"""Pure host byte-contract tests; no assembler, model or device is invoked."""
import struct
import unittest

import patch


# Exact raw bytes extracted from the coordinator-assembled gfx1151 fixture,
# not generated by the patcher's own encoder or an independently guessed ISA.
FIXTURE = bytes.fromhex(
    "fa02047e156809fffa02087e136809fffa02067e146809fffa02027e106809ff"
    "fa020c7e026409fffa02107e046409fffa020e7e036409fffa02107e066209ff"
    "fa020a7e016409fffa02027e026209fffa020a7e036209fffa02167e076209ff"
    "fa020c7e046109fffa02047e016109fffa020e7e056109fffa02067e006109ff"
)
FIXTURE_SHA = "602cde275166ac1097e6b5cc27ea7e2e3efb6ebeb83d109f4c44288fe0845540"


class PatchContract(unittest.TestCase):
    def source_slots(self):
        source = bytearray(b"\xa5" * (patch.EXCHANGES[-1].file_offset + 32))
        for e in patch.EXCHANGES:
            source[e.file_offset:e.file_offset + 8] = e.original
        return bytes(source)

    def test_coordinator_fixture_is_accepted(self):
        self.assertEqual(patch.sha256(FIXTURE), FIXTURE_SHA)
        parts = patch.validate_fixture(FIXTURE, FIXTURE_SHA)
        self.assertEqual(len(parts), 16)

    def test_operand_or_control_tampering_is_rejected(self):
        original = FIXTURE[:8]
        for word, mask in [(0, 1 << 17), (1, 1), (1, 1 << 8),
                           (1, 1 << 19), (1, 1 << 24), (1, 1 << 28)]:
            altered = bytearray(original)
            value = struct.unpack_from("<I", altered, 4 * word)[0] ^ mask
            struct.pack_into("<I", altered, 4 * word, value)
            with self.subTest(word=word, mask=mask):
                with self.assertRaises(ValueError):
                    patch.validate_dpp_instruction(patch.EXCHANGES[0], bytes(altered))

    def test_only_exact_instruction_slots_change(self):
        source = self.source_slots()
        candidate = patch.replace_exchanges(source,
                    tuple(FIXTURE[i:i + 8] for i in range(0, 128, 8)))
        allowed = {p for e in patch.EXCHANGES
                   for p in range(e.file_offset, e.file_offset + 8)}
        differences = {i for i, (a, b) in enumerate(zip(source, candidate)) if a != b}
        self.assertTrue(differences)
        self.assertLessEqual(differences, allowed)
        self.assertEqual(source[patch.KD_FILE_OFFSET:patch.KD_FILE_OFFSET + 64],
                         candidate[patch.KD_FILE_OFFSET:patch.KD_FILE_OFFSET + 64])
        self.assertEqual(len(source), len(candidate))
        patch.prove_changed_ranges(source, candidate)
        mutated = bytearray(candidate)
        mutated[patch.KD_FILE_OFFSET] ^= 1
        with self.assertRaises(ValueError):
            patch.prove_changed_ranges(source, bytes(mutated))

    def test_wrong_source_or_fixture_does_not_produce_candidate(self):
        source = bytearray(self.source_slots())
        source[patch.EXCHANGES[3].file_offset] ^= 1
        with self.assertRaises(ValueError):
            patch.replace_exchanges(bytes(source),
                    tuple(FIXTURE[i:i + 8] for i in range(0, 128, 8)))
        with self.assertRaises(ValueError):
            patch.verify_original(self.source_slots())
        with self.assertRaises(ValueError):
            patch.validate_fixture(FIXTURE[:-1], FIXTURE_SHA)
        with self.assertRaises(ValueError):
            patch.validate_fixture(FIXTURE, "0" * 64)

    def test_bit_exchange_preserves_two_independent_sixteen_lane_rows(self):
        # Arbitrary uint32 payloads model a bit move, including NaN-like words.
        words = [((lane * 0x9e3779b9) ^ 0x7fc00001) & 0xffffffff
                 for lane in range(32)]
        for distance in (8, 4, 2, 1):
            ds_result = [words[(4 * (lane ^ distance)) // 4] for lane in range(32)]
            dpp_result = [words[(lane & ~15) | ((lane & 15) ^ distance)]
                          for lane in range(32)]
            self.assertEqual(ds_result, dpp_result)
            for lane in range(32):
                self.assertEqual((lane ^ distance) // 16, lane // 16)


if __name__ == "__main__":
    unittest.main()
